/**
 * The website's typefaces (decision R1 of .plans/DOCS_SITE_REDESIGN_PLAN.md): Overpass for
 * headings and text, Overpass Mono for code, served from the site itself, so visitors never fetch
 * from Google - and, since the files are committed (docs/fonts/, SIL Open Font License), neither
 * does the build.
 *
 * GENERATED by scripts/build-doc-fonts.cjs - run it to update the fonts; do not edit by hand.
 * next/font only accepts literal arguments, hence a generated module rather than a data file.
 *
 * Each family is Google's latin + latin-ext split: two faces with one family name and their own
 * unicode-range. Each exposes a CSS variable that app/tokens.css builds its font stacks on.
 */
import localFont from "next/font/local";

const body = localFont({
  src: [
    { path: "../fonts/overpass-latin.woff2", weight: "400 800", style: "normal" },
    { path: "../fonts/overpass-italic-latin.woff2", weight: "400 800", style: "italic" }
  ],
  declarations: [
    { prop: "font-family", value: "Overpass" },
    { prop: "unicode-range", value: "U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD" }
  ],
  variable: "--font-body",
  display: "swap"
});

const bodyExt = localFont({
  src: [
    { path: "../fonts/overpass-latin-ext.woff2", weight: "400 800", style: "normal" },
    { path: "../fonts/overpass-italic-latin-ext.woff2", weight: "400 800", style: "italic" }
  ],
  declarations: [
    { prop: "font-family", value: "Overpass" },
    { prop: "unicode-range", value: "U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF" }
  ],
  variable: "--font-body-ext",
  adjustFontFallback: false,
  display: "swap"
});

const mono = localFont({
  src: [
    { path: "../fonts/overpass-mono-latin.woff2", weight: "400 600", style: "normal" }
  ],
  declarations: [
    { prop: "font-family", value: "Overpass Mono" },
    { prop: "unicode-range", value: "U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD" }
  ],
  variable: "--font-mono",
  display: "swap"
});

const monoExt = localFont({
  src: [
    { path: "../fonts/overpass-mono-latin-ext.woff2", weight: "400 600", style: "normal" }
  ],
  declarations: [
    { prop: "font-family", value: "Overpass Mono" },
    { prop: "unicode-range", value: "U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF" }
  ],
  variable: "--font-mono-ext",
  adjustFontFallback: false,
  display: "swap"
});

/** The class names that define the font variables; put them on <html>. */
export const fontVariables = [body, bodyExt, mono, monoExt].map((font) => font.variable).join(" ");
